<div id="controls" class="drawer-controls"><div><div class="btn-row"><button class="control-btn active" data-pre="mitosis">MITOSIS</button><button class="control-btn" data-pre="coral">CORAL</button><button class="control-btn" data-pre="maze">MAZE</button></div></div><div><div class="slider-row"><span class="slider-label">FEED</span><input type="range" id="sl-feed" min="18" max="62" value="36"><span class="slider-value" id="sv-feed">0.036</span></div></div><div><div class="slider-row"><span class="slider-label">KILL</span><input type="range" id="sl-kill" min="45" max="75" value="60"><span class="slider-value" id="sv-kill">0.060</span></div></div><div><div class="btn-row"><button class="control-btn active" id="btn-run">RUN</button><button class="control-btn" id="btn-reset">RESET</button></div></div></div><?php require_once __DIR__ . '/includes/drawer-controls.php';?>
<script>(function(){var c=document.getElementById('canvas'),x=c.getContext('2d'),W,H,D=1,N=138,M=84,a,b,na,nb,img,buf,bx,feed=.036,kill=.060,run=true,seeds=0,pre='mitosis';var hp=document.getElementById('h-pre'),hf=document.getElementById('h-feed'),hk=document.getElementById('h-kill'),hz=document.getElementById('h-seeds'),sf=document.getElementById('sl-feed'),sk=document.getElementById('sl-kill'),vf=document.getElementById('sv-feed'),vk=document.getElementById('sv-kill'),br=document.getElementById('btn-run');function resize(){D=Math.min(2,devicePixelRatio||1);W=c.width=Math.floor(innerWidth*D);H=c.height=Math.floor(innerHeight*D);c.style.width=innerWidth+'px';c.style.height=innerHeight+'px';N=innerWidth<760?96:150;M=Math.max(60,Math.round(N*H/W));reset()}function ix(i,j){return j*N+i}function reset(){a=new Float32Array(N*M);b=new Float32Array(N*M);na=new Float32Array(N*M);nb=new Float32Array(N*M);img=x.createImageData(N,M);buf=document.createElement('canvas');buf.width=N;buf.height=M;bx=buf.getContext('2d');a.fill(1);for(var k=0;k<8;k++)seed(Math.random(),Math.random(),7);seeds=8;hz.textContent=seeds}function seed(nx,ny,r){var cx=Math.floor(nx*(N-1)),cy=Math.floor(ny*(M-1));for(var y=-r;y<=r;y++)for(var xx=-r;xx<=r;xx++){var i=cx+xx,j=cy+y;if(i>1&&j>1&&i<N-2&&j<M-2&&xx*xx+y*y<r*r){b[ix(i,j)]=1;a[ix(i,j)]=0}}}function lap(arr,i,j){var k=ix(i,j);return arr[k]*-1+arr[ix(i-1,j)]*.2+arr[ix(i+1,j)]*.2+arr[ix(i,j-1)]*.2+arr[ix(i,j+1)]*.2+arr[ix(i-1,j-1)]*.05+arr[ix(i+1,j-1)]*.05+arr[ix(i-1,j+1)]*.05+arr[ix(i+1,j+1)]*.05}function step(){for(var j=1;j<M-1;j++)for(var i=1;i<N-1;i++){var k=ix(i,j),av=a[k],bv=b[k],react=av*bv*bv;na[k]=av+(1*lap(a,i,j)-react+feed*(1-av));nb[k]=bv+(.5*lap(b,i,j)+react-(kill+feed)*bv);if(na[k]<0)na[k]=0;if(na[k]>1)na[k]=1;if(nb[k]<0)nb[k]=0;if(nb[k]>1)nb[k]=1}var ta=a;a=na;na=ta;var tb=b;b=nb;nb=tb}function draw(){if(run)for(var s=0;s<8;s++)step();var d=img.data;for(var j=0;j<M;j++)for(var i=0;i<N;i++){var k=ix(i,j),v=b[k],u=a[k],m=Math.max(0,Math.min(1,v*1.7));var o=k*4;d[o]=Math.floor(8+115*m);d[o+1]=Math.floor(22+223*(1-Math.abs(u-v)));d[o+2]=Math.floor(38+174*m);d[o+3]=255}bx.putImageData(img,0,0);x.imageSmoothingEnabled=true;x.drawImage(buf,0,0,W,H);requestAnimationFrame(draw)}function hud(){hp.textContent=pre.toUpperCase();hf.textContent=feed.toFixed(3);hk.textContent=kill.toFixed(3);vf.textContent=feed.toFixed(3);vk.textContent=kill.toFixed(3)}function paint(e){seed(e.clientX/innerWidth,e.clientY/innerHeight,7);seeds++;hz.textContent=seeds;if(typeof SFX!=='undefined')SFX.play('spawn',120)}c.addEventListener('pointerdown',e=>paint(e));c.addEventListener('pointermove',e=>{if(e.buttons)paint(e)});document.querySelectorAll('[data-pre]').forEach(btn=>btn.onclick=()=>{pre=btn.dataset.pre;if(pre==='mitosis'){feed=.036;kill=.060}else if(pre==='coral'){feed=.054;kill=.063}else{feed=.029;kill=.057}sf.value=Math.round(feed*1000);sk.value=Math.round(kill*1000);document.querySelectorAll('[data-pre]').forEach(q=>q.classList.toggle('active',q===btn));hud();if(typeof SFX!=='undefined')SFX.play('toggle')});sf.oninput=()=>{feed=+sf.value/1000;hud()};sk.oninput=()=>{kill=+sk.value/1000;hud()};br.onclick=()=>{run=!run;br.classList.toggle('active',run);if(typeof SFX!=='undefined')SFX.play('toggle')};document.getElementById('btn-reset').onclick=()=>{reset();if(typeof SFX!=='undefined')SFX.play('success')};addEventListener('resize',resize);resize();hud();draw()})();</script><?php require_once __DIR__ . '/includes/sfx.php';require_once __DIR__ . '/includes/page-end.php';?></body></html>